// app/api/report/route.ts
export const runtime = "edge";

import { readFile } from "node:fs/promises";
import { Client } from "pg";
import { renderReport } from "~/lib/render-report";

export async function GET(request: Request) {
  const userId = new URL(request.url).searchParams.get("user")!;
  const template = await readFile("./templates/report.html", "utf8");

  const db = new Client({ connectionString: process.env.DATABASE_URL });
  await db.connect();

  const user = await db.query("SELECT * FROM users WHERE id = $1", [userId]);
  const orders = await db.query(
    "SELECT * FROM orders WHERE user_id = $1 AND region = $2",
    [userId, user.rows[0].region],
  );

  return new Response(
    renderReport(template, { user: user.rows[0], orders: orders.rows }),
    { headers: { "content-type": "text/html" } },
  );
}
